def differences(expected, observed):
    return [(name, expected.get(name), observed.get(name))
            for name in sorted(set(expected) | set(observed))
            if expected.get(name) != observed.get(name)]

expected = {'a-demo': '1', 'b-demo': '2'}
observed = {'a-demo': '3', 'c-demo': '1'}
assert differences(expected, observed) == [
    ('a-demo', '1', '3'), ('b-demo', '2', None), ('c-demo', None, '1')]
print('resolved-set differences checked')
